from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from itertools import combinations

G = 30
W = 7
K = 10  # groups per week
S = 3   # group size

# Variables: x[w][p][g] = golfer p in group g in week w
# pair[w][i][j] = golfers i,j in same group in week w

def var_x(w, p, g):
    return 1 + w * G * K + p * K + g

max_x = W * G * K

pair_var = {}
cnt = max_x
for w in range(W):
    for i in range(G):
        for j in range(i+1, G):
            cnt += 1
            pair_var[(w,i,j)] = cnt

solver = Glucose4()
top_id = cnt

def add_clause(c):
    solver.add_clause(c)

# Each golfer in exactly one group per week
for w in range(W):
    for p in range(G):
        lits = [var_x(w,p,g) for g in range(K)]
        add_clause(lits)
        for a,b in combinations(lits, 2):
            add_clause([-a,-b])

# Each group has exactly S players per week
# Use CardEnc
from pysat.formula import IDPool, CNF
# Easier: build CNF with IDPool to handle cardinality
vpool = IDPool(start_from=top_id+1)

cnf_extra = CNF()
for w in range(W):
    for g in range(K):
        lits = [var_x(w,p,g) for p in range(G)]
        enc = CardEnc.equals(lits=lits, bound=S, top_id=vpool.top, encoding=EncType.seqcounter)
        for cl in enc.clauses:
            cnf_extra.append(cl)
            for l in cl:
                if abs(l) > vpool.top:
                    vpool.top = abs(l)

for cl in cnf_extra.clauses:
    add_clause(cl)

# pair_var definition: pair[w,i,j] <=> exists g: x[w,i,g] AND x[w,j,g]
# We need: if pair true then some group has both; but easier:
# Define: for each w,i,j: pair iff they're in same group.
# pair_var[w,i,j] -> OR_g (x[w,i,g] AND x[w,j,g])
# And reverse: x[w,i,g] AND x[w,j,g] -> pair_var[w,i,j]
# For the no-repeat constraint, we only need: sum_w pair_var[w,i,j] <= 1
# So we need: x[w,i,g] AND x[w,j,g] -> pair_var[w,i,j]
# That's: -x[w,i,g] OR -x[w,j,g] OR pair_var[w,i,j]

for w in range(W):
    for i in range(G):
        for j in range(i+1, G):
            pv = pair_var[(w,i,j)]
            for g in range(K):
                add_clause([-var_x(w,i,g), -var_x(w,j,g), pv])

# No pair in same group more than once
for i in range(G):
    for j in range(i+1, G):
        lits = [pair_var[(w,i,j)] for w in range(W)]
        enc = CardEnc.atmost(lits=lits, bound=1, top_id=vpool.top, encoding=EncType.seqcounter)
        for cl in enc.clauses:
            for l in cl:
                if abs(l) > vpool.top:
                    vpool.top = abs(l)
            add_clause(cl)

print("Solving...")
res = solver.solve()
print("SAT:", res)
if res:
    model = solver.get_model()
    mset = set(model)
    sched = []
    for w in range(W):
        for p in range(G):
            for g in range(K):
                if var_x(w,p,g) in mset:
                    sched.append(g)
                    break
    print(len(sched))
    # Verify
    ok = True
    seen = set()
    for w in range(W):
        groups = {}
        for p in range(G):
            groups.setdefault(sched[w*G+p], []).append(p)
        for g, ps in groups.items():
            if len(ps) != 3:
                ok = False
                print("bad group size", w, g, ps)
            for a,b in combinations(ps,2):
                if (a,b) in seen:
                    ok = False
                    print("repeat", a,b)
                seen.add((a,b))
    print("valid:", ok)
    print(sched)
